import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append("\n");
        }
        String input = sb.toString().trim();
        String[] inp = input.split("\\s+");
        int n = Integer.parseInt(inp[0]);
        int k = Integer.parseInt(inp[1]);
        String s = inp[2];
        String t = inp[3];

        if (t.charAt(0) == t.charAt(1)) {
            int count = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == t.charAt(0)) count++;
            }
            int x = Math.min(count + k, n);
            long ans = (long) x * (x - 1) / 2;
            System.out.println(ans);
            return;
        }

        int size = n + 2;
        int[][][] f = new int[size][size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                for (int l = 0; l < size; l++) {
                    f[i][j][l] = -100000;
                }
            }
        }
        f[0][0][0] = 0;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int cnt0 = 0; cnt0 <= i; cnt0++) {
                    if (f[i][j][cnt0] < 0) continue;

                    char c = (i < s.length()) ? s.charAt(i) : '\0';
                    int e0 = (c == t.charAt(0)) ? 1 : 0;
                    int e1 = (c == t.charAt(1)) ? 1 : 0;

                    int idx1 = cnt0 + e0;
                    int val1 = f[i][j][cnt0] + e1 * cnt0;
                    if (val1 > f[i + 1][j][idx1]) {
                        f[i + 1][j][idx1] = val1;
                    }

                    int idx2 = cnt0 + 1;
                    int val2 = f[i][j][cnt0];
                    if (val2 > f[i + 1][j + 1][idx2]) {
                        f[i + 1][j + 1][idx2] = val2;
                    }

                    int val3a = f[i + 1][j][cnt0];
                    int val3b = f[i][j][cnt0] + cnt0;
                    int val3 = Math.max(val3a, val3b);
                    if (val3 > f[i + 1][j + 1][cnt0]) {
                        f[i + 1][j + 1][cnt0] = val3;
                    }
                }
            }
        }

        int best = Integer.MIN_VALUE;
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                if (f[n][i][j] > best) {
                    best = f[n][i][j];
                }
            }
        }

        System.out.println(best);
    }
}
